#include <Adafruit_NeoPixel.h>

#define DATA_PIN 2
#define NUM_PIXELS 64

Adafruit_NeoPixel pixels(NUM_PIXELS, DATA_PIN, NEO_GRB + NEO_KHZ800);

void setup() {
  pixels.begin();
  pixels.setBrightness(50);
  Serial1.setTX(0);
  Serial1.setRX(1);
  Serial1.begin(115200);
  Serial1.println("8X8_NEOPIXEL_BOOT");
}

void loop() {
  static int pos = 0;
  pixels.clear();
  pixels.setPixelColor(pos, pixels.Color(0, 255, 0)); // Scanning Green dot
  pixels.show();

  Serial1.print("NEO_POS: ");
  Serial1.println(pos);

  pos = (pos + 1) % NUM_PIXELS;
  delay(20);
}

